package com.birdhouserunnotifier;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;

@ConfigGroup("birdhouserunnotifier")
public interface BirdhouseRunNotifierConfig extends Config
{
	@ConfigSection(
		name = "Requires 'Time Tracking' plugin",
		description = "This plugin requires the RuneLite Time Tracking plugin to be active.",
		position = 0
	)
	String timeTrackingReminder = "timeTrackingReminder";

	@ConfigItem(
		keyName = "customNotification",
		name = "Custom notification",
		description = "Configure the notification used when bird houses are ready",
		position = 3
	)
	default Notification customNotification()
	{
		return Notification.OFF;
	}

	@Range(
		min = 0,
		max = 100
	)
	@ConfigItem(
		keyName = "soundVolume",
		name = "Sound Volume",
		description = "Volume of the bird notification sound (0-100)",
		position = 1
	)
	default int soundVolume()
	{
		return 15;
	}

	@ConfigItem(
		keyName = "testAlert",
		name = "Test Alert",
		description = "Check this box to send a test message to the chat and verify the sound",
		position = 4
	)
	default boolean testAlert()
	{
		return false;
	}
}

package com.birdhouserunnotifier;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.Notifier;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.GameState;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.List;
import java.time.Instant;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import net.runelite.client.util.ColorUtil;
import java.awt.Color;

@Slf4j
@PluginDescriptor(
	name = "Birdhouse Run Notifier",
	description = "Plays a short song when bird houses are ready",
	tags = {"birdhouse", "hunter", "alert", "sound", "time tracking","alert","bird","run"}
)
public class BirdhouseRunNotifierPlugin extends Plugin
{
	private static final String NOTIFICATION_MESSAGE = "Your bird houses are ready to be dismantled.";
	private static final String CUSTOM_NOTIFICATION_ANNOUNCEMENT_START = "customNotificationAnnouncementStart";
	private static final long CUSTOM_NOTIFICATION_ANNOUNCEMENT_DURATION_SECONDS = TimeUnit.DAYS.toSeconds(10);
	private static final String CUSTOM_NOTIFICATION_ANNOUNCEMENT =
		"Birdhouse Run Notifier now supports custom notifications. Enable Custom notification in the plugin settings to configure it.";

	@Inject
	private Client client;

	@Inject
	private BirdhouseRunNotifierConfig config;

	@Inject
	private AudioPlayer audioPlayer;

	@Inject
	private Notifier notifier;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	private ScheduledFuture<?> notificationTask;
	private long targetCompletionTime = 0;
	private boolean customNotificationAnnouncementShown;

	@Override
	protected void startUp() throws Exception
	{
		log.debug("Birdhouse run notifier started!");
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			recalculateCompletionTime();
			checkTimeTrackingPlugin();
			announceCustomNotification();
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		cancelNotification();
		log.debug("Birdhouse run notifier stopped!");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			recalculateCompletionTime();
			checkTimeTrackingPlugin();
			announceCustomNotification();
		}
	}

	private void announceCustomNotification()
	{
		if (customNotificationAnnouncementShown)
		{
			return;
		}

		long now = Instant.now().getEpochSecond();
		String configuredStart = configManager.getConfiguration(
			"birdhouserunnotifier",
			CUSTOM_NOTIFICATION_ANNOUNCEMENT_START);
		long announcementStart;

		try
		{
			announcementStart = configuredStart == null ? 0 : Long.parseLong(configuredStart);
		}
		catch (NumberFormatException e)
		{
			log.debug("Invalid custom notification announcement start time: {}", configuredStart);
			announcementStart = 0;
		}

		if (announcementStart == 0)
		{
			announcementStart = now;
			configManager.setConfiguration(
				"birdhouserunnotifier",
				CUSTOM_NOTIFICATION_ANNOUNCEMENT_START,
				announcementStart);
		}

		if (now - announcementStart >= CUSTOM_NOTIFICATION_ANNOUNCEMENT_DURATION_SECONDS)
		{
			return;
		}

		customNotificationAnnouncementShown = true;
		clientThread.invokeLater(() ->
		{
			String message = ColorUtil.wrapWithColorTag(CUSTOM_NOTIFICATION_ANNOUNCEMENT,
				Color.GREEN);
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals("birdhouserunnotifier") && event.getKey().equals("testAlert"))
		{
			if (config.testAlert())
			{
				// Reset the config toggle back to false so it acts like a button
				configManager.setConfiguration("birdhouserunnotifier", "testAlert", false);

				if (config.customNotification().isEnabled())
				{
					sendTestNotification();
				}
				else
				{
					// Preserve the existing test behavior when custom notifications are disabled.
					clientThread.invokeLater(() ->
						client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", NOTIFICATION_MESSAGE, null));
					playBirdSound();
				}
			}
		}
		else if (event.getGroup().equals("timetracking") && event.getKey().contains("birdhouse"))
		{
			long completionTime = parseCompletionTime(event.getNewValue());
			log.debug("Caught birdhouse config change: {} -> {}", event.getKey(), completionTime);

			// We save the latest time we've seen
			if (completionTime > targetCompletionTime)
			{
				targetCompletionTime = completionTime;
				scheduleNotification(targetCompletionTime);
				configManager.setConfiguration("birdhouserunnotifier", "latestCompletionTime", targetCompletionTime);
			}
		}
	}

	private void recalculateCompletionTime()
	{
		// Instead of guessing Time Tracking's profile keys, we just read the latest time we saved ourselves!
		String value = configManager.getConfiguration("birdhouserunnotifier", "latestCompletionTime");
		if (value != null)
		{
			try
			{
				long completionTime = Long.parseLong(value);
				targetCompletionTime = completionTime;
				scheduleNotification(completionTime);
			}
			catch (Exception e)
			{
				log.debug("Failed to parse saved completion time.");
			}
		}
		else
		{
			log.debug("No active birdhouses found to schedule.");
		}
	}

// send a system message to let the user know he needs to enable "Time tracking plugin"
	private void checkTimeTrackingPlugin()
	{
		String timeTrackingEnabled = configManager.getConfiguration("runelite", "timetrackingplugin");
		if ("false".equals(timeTrackingEnabled))
		{
			clientThread.invokeLater(() ->
			{
				String message = ColorUtil.wrapWithColorTag("Birdhouse Run Notifier:", Color.RED) +
					" Please enable the Time Tracking plugin for this plugin to work properly.";
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
			});
		}
	}

	private long parseCompletionTime(String value)
	{
		try
		{
			// Time tracking saves it as "state:timestamp" (e.g., 24:1785908336)
			// The timestamp is the exact moment the birdhouse was PLANTED, not when it finishes.
			long startTime = 0;
			if (value.contains(":"))
			{
				String[] parts = value.split(":");
				startTime = Long.parseLong(parts[1]);
			}
			else
			{
				startTime = Long.parseLong(value);
			}

			// Birdhouses take exactly 50 minutes to complete (50 * 60 = 3000 seconds)
			// We add an extra 90 seconds because the time tracking plugin can sometimes alert early
			return startTime + 3090;
		}
		catch (NumberFormatException e)
		{
			// If it's JSON, extract the timestamp field if it exists
			try
			{
				JsonObject obj = gson.fromJson(value, JsonObject.class);
				if (obj != null)
				{
					if (obj.has("timestamp"))
					{
						return obj.get("timestamp").getAsLong();
					}
					else if (obj.has("time"))
					{
						return obj.get("time").getAsLong();
					}
				}
			}
			catch (Exception ex)
			{
				log.debug("Failed to parse birdhouse config value: {}", value);
			}
		}
		return 0;
	}

	private void scheduleNotification(long completionTimeUnixSec)
	{
		long currentTimeSec = Instant.now().getEpochSecond();
		long delaySec = completionTimeUnixSec - currentTimeSec;

		cancelNotification();

		if (delaySec > 0)
		{
			log.debug("Scheduling birdhouse notification in {} seconds", delaySec);
			notificationTask = executor.schedule(() -> {
				log.debug("Birdhouse timer reached! Playing sound.");
				sendNotification();
			}, delaySec, TimeUnit.SECONDS);
		}
		else
		{
			// It is already completed, no need to schedule, or maybe we just logged in and it's done.
			// But we don't want to play sound immediately on login if it was completed hours ago.
			log.debug("Birdhouses are already completed.");
		}
	}

	private void cancelNotification()
	{
		if (notificationTask != null && !notificationTask.isDone())
		{
			notificationTask.cancel(false);
			notificationTask = null;
		}
	}

	private void sendNotification()
	{
		if (config.customNotification().isEnabled())
		{
			sendCustomNotification();
		}
		else
		{
			playBirdSound();
		}
	}

	private void sendCustomNotification()
	{
		clientThread.invokeLater(() -> notifier.notify(config.customNotification(), NOTIFICATION_MESSAGE));
	}

	private void sendTestNotification()
	{
		clientThread.invokeLater(() -> notifier.notify(
			config.customNotification()
				.withEnabled(true)
				.withSendWhenFocused(true),
			NOTIFICATION_MESSAGE));
	}

	private void playBirdSound()
	{
		int volumeConfig = config.soundVolume();
		if (volumeConfig <= 0)
		{
			return;
		}

		try
		{
			// Convert the linear volume (1-100) to a decibel scale (-40dB to 0dB)
			float volume = Math.max(1f, Math.min(100f, volumeConfig));
			float decibels = (float) (Math.log10(volume / 100f) * 20f);

			// Play the custom bird sound using RuneLite's AudioPlayer
			audioPlayer.play(this.getClass(), "/bird_notification.wav", decibels);
			log.debug("Bird sound played via AudioPlayer with dB: {}", decibels);
		}
		catch (Exception e)
		{
			log.warn("Error playing bird notification sound: {}", e.getMessage());
		}
	}

	@Provides
	BirdhouseRunNotifierConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BirdhouseRunNotifierConfig.class);
	}
}

package com.birdhouserunnotifier;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BirdhouseRunNotifierTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BirdhouseRunNotifierPlugin.class);
		RuneLite.main(args);
	}
}
